const ChangePassword = () => {
  const [formData, setFormData] = useState({ oldpw: '', newpw: '', newpwrep: '' });
  // const navigate = useNavigate();

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      await axiosInstance.post('/api/auth/change-password', formData);
      alert('Password changed successfully.');

    } catch (error) {
      alert('Password change failed. Please try again.');
    }
  };

  return (
    <div className="max-w-md mx-auto mt-20">
      <form onSubmit={handleSubmit} className="bg-white p-6 shadow-md rounded">
        <h1 className="text-2xl font-bold mb-4 text-center">Change Password</h1>
        <input
          type="password"
          placeholder="Old Password"
          value={formData.oldpw}
          onChange={(e) => setFormData({ ...formData, oldpw: e.target.value })}
          className="w-full mb-4 p-2 border rounded"
        />
        <input
          type="password"
          placeholder="New Password"
          value={formData.newpw}
          onChange={(e) => setFormData({ ...formData, newpw: e.target.value })}
          className="w-full mb-4 p-2 border rounded"
        />
        <input
          type="password"
          placeholder="Repeat New Password"
          value={formData.newpwrep}
          onChange={(e) => setFormData({ ...formData, newpwrep: e.target.value })}
          className="w-full mb-4 p-2 border rounded"
        />

        <button type="submit" className="w-full bg-green-600 text-white p-2 rounded">
          Change Password
        </button>
      </form>
    </div>
  );
};

export default ChangePassword;
